class TFMRegistrationCollectorInformation extends TFMRegistrationCollector
{

    /// <summary>
    /// Creates a collectorstep for displaying or capturing long strings
    /// </summary>
    /// <param name="_id"></param>
    /// <param name="_name"></param>
    /// <param name="_header"></param>
    /// <param name="_lable"></param>
    /// <param name="_helpLabel"></param>


